arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_726d3d17796c4c5a9a70109cfed45329.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        <h3>✅ Application Submitted Successfully!</h3>
        <p>Your application ID is: <strong>@applicationId</strong></p>
        <p>Thank you for applying. We will review your application and get back to you.</p>
    </div>
}
else
{
    <!-- Step Indicator Bar -->
    <nav class="step-indicator mb-4">
        <ol class="d-flex list-unstyled justify-content-between p-0">
            @for (int i = 0; i < stepNames.Length; i++)
            {
                var stepIndex = i;
                var isCompleted = stepIndex < currentStep;
                var isCurrent = stepIndex == currentStep;
                var isFuture = stepIndex > currentStep;

                <li class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    @onclick="() => GoToStep(stepIndex)"
                    style="cursor: @(isCompleted ? "pointer" : "default"); flex: 1; text-align: center; padding: 0.5rem;">
                    <div class="step-circle @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted")"
                         style="width: 32px; height: 32px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-weight: bold;">
                        @if (isCompleted)
                        {
                            <span>✓</span>
                        }
                        else
                        {
                            <span>@(stepIndex + 1)</span>
                        }
                    </div>
                    <div class="step-label mt-1 small @(isFuture ? "text-muted" : "")">@stepNames[stepIndex]</div>
                </li>
            }
        </ol>
    </nav>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <div class="alert alert-danger">@errorMessage</div>
    }

    <!-- Step 1: Personal Info -->
