            <div class="form-text text-end">@(coverLetter?.Length ?? 0) / 2000 characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    }

    <!-- Step 5: Review & Submit -->
    @if (currentStep == 4)
    {
        <h3>Review & Submit</h3>

        <!-- Personal Info Review -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <a href="#" @onclick="() => GoToStep(0)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Full Name</dt>
                    <dd class="col-sm-9">@fullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@address</dd>
