        <!-- Work History Review -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <a href="#" @onclick="() => GoToStep(1)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @foreach (var entry in workEntries)
                {
                    <div class="mb-3 pb-3 border-bottom">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <!-- References Review -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <a href="#" @onclick="() => GoToStep(2)" @onclick:preventDefault>Edit</a>
            </div>
            <div class="card-body">
                @foreach (var r in references)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span class="text-muted">@r.Email | @r.Phone</span>
                    </div>
                }
            </div>
        </div>

        <!-- Cover Letter Review -->
